import fs from 'node:fs';import {createRequire} from 'node:module';import {render,sample} from './clock-v7.mjs';const req=createRequire(import.meta.url),sharp=req(process.env.CODEX_PRIMARY_RUNTIME_NODE_MODULES+'/sharp');
const art='data:image/png;base64,'+fs.readFileSync(new URL('../assets/dial-art-v4.png',import.meta.url)).toString('base64');const images=[];
for(const v of ['reference','candidate'])images.push(await sharp(Buffer.from(render(sample,{variant:v}).replaceAll('../assets/dial-art-v4.png',art))).resize(600,600).png().toBuffer());
await sharp({create:{width:1200,height:650,channels:3,background:'#f5f6f5'}}).composite([{input:images[0],left:0,top:40},{input:images[1],left:600,top:40},{input:Buffer.from('<svg width="1200" height="40"><text x="300" y="28" text-anchor="middle" font-size="20" fill="#233e4e">VERSION 6 / B</text><text x="900" y="28" text-anchor="middle" font-size="20" fill="#233e4e">VERSION 7</text></svg>'),left:0,top:0}]).jpeg({quality:90}).toFile(new URL('evidence/comparison.jpg',import.meta.url).pathname);
